## 2. Output Sink
The surface-agnostic event bus. Core modules emit events; adapters handle them.
```rust
// src/sink/mod.rs
#[derive(Debug)]
pub enum AgentEvent {
    StepStarted    { id: String, name: String, level: u32 },
    StepCompleted  { id: String, duration: Duration },
    StepSkipped    { id: String, reason: SkipReason },
    StepFailed     { id: String, error: AgentError, retryable: bool },
    RetryScheduled { label: String, attempt: u32, max: u32, wait: Duration },
    CircuitOpened  { name: String, retry_after: Duration },
    PipelineFinished(PipelineResult),
    /// Generic structured payload — surface decides how to present it.
    Data(serde_json::Value),
    Warn(String),
    Info(String),
}
pub trait OutputSink: Send + Sync {
    fn emit(&self, event: AgentEvent);
}
/// Default: discard all events.
pub struct NoopSink;
impl OutputSink for NoopSink {
    fn emit(&self, _: AgentEvent) {}
}
