## 4. Pipeline Execution
### Core types
```rust
// src/pipeline/step.rs
pub type StepOutput = serde_json::Value;
#[async_trait]
pub trait StepFn: Send + Sync {
    async fn run(&self, ctx: &StepContext) -> Result<StepOutput, AgentError>;
}
pub struct Step {
    pub id: String,
    pub name: String,
    pub level: u32,                       // steps at same level run concurrently
    pub depends_on: Vec<String>,          // level is derived from this if level=0
    pub idempotency_key: Option<String>,  // cache hit → Skipped::Idempotent
    pub best_effort: bool,                // failure → Skipped::BestEffortFailed, not Failed
    pub run: Arc<dyn StepFn>,
}
pub struct StepContext {
    pub run_id: Uuid,
    pub step_id: String,
    pub outputs: Arc<HashMap<String, StepOutput>>, // completed upstream step outputs
    pub cancel: CancellationToken,
}
#[derive(Debug, Clone)]
pub enum StepStatus {
    Pending,
    Running,
    Completed { output: StepOutput, duration: Duration },
    Skipped   { reason: SkipReason },
    Failed    { error: String, retryable: bool, retry_with: Option<StepOutput> },
}
#[derive(Debug, Clone)]
pub enum SkipReason {
    Idempotent,          // idempotency_key hit cache
    DependencyFailed,    // upstream step failed
    BestEffortFailed,    // step.best_effort = true and step failed
    Cancelled,           // cancellation token fired before step started
}
