8	/// Configuration for automatic retry behaviour.
9	///
10	/// Callers implement the retry loop; michi provides the delay computation via
11	/// [`next_retry_delay`]. This keeps the crate sync and runtime-agnostic.
12	#[derive(Debug, Clone)]
13	pub struct RetryConfig {
14	    /// Maximum number of retry attempts (not counting the initial attempt).
15	    pub max_retries: u32,
16	    /// Base delay for exponential back-off.
17	    pub base_delay: Duration,
18	    /// Maximum delay cap — back-off never exceeds this.
19	    pub max_delay: Duration,
20	    /// Jitter factor in `[0.0, 1.0]`. `0.0` = no jitter, `1.0` = full jitter.
21	    pub jitter_factor: f64,
22	}
23	
24	// Manually implemented because the defaults are meaningful non-zero values
25	// that `#[derive(Default)]` cannot express (it would set all durations to zero).
26	impl Default for RetryConfig {
27	    fn default() -> Self {
28	        Self {
29	            max_retries: 3,
30	            base_delay: Duration::from_millis(500),
31	            max_delay: Duration::from_secs(30),
32	            jitter_factor: 0.2,
33	        }
34	    }
35	}
36	
37	/// Compute the delay before the next retry attempt.
38	///
39	/// Uses exponential back-off: `base_delay * 2^attempt`, capped at
40	/// `max_delay`, with optional jitter derived from `jitter_seed` (a value in
41	/// `[0.0, 1.0]` supplied by the caller — use a PRNG, not `rand` inside michi).
42	///
43	/// Returns `None` when `attempt >= config.max_retries`.
44	#[must_use]
45	// Casts are safe: delays are capped at max_delay (≤ 30 s by default, well within u64 ms range).
46	// jitter_seed is documented as [0.0, 1.0], so the f64 product is non-negative and bounded.
47	#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss, clippy::cast_sign_loss)]
48	pub fn next_retry_delay(config: &RetryConfig, attempt: u32, jitter_seed: f64) -> Option<Duration> {
49	    if attempt >= config.max_retries {
50	        return None;
51	    }
52	    let exp = 2u64.saturating_pow(attempt);
53	    let base_ms = config.base_delay.as_millis() as u64;
54	    let raw_ms = base_ms.saturating_mul(exp);
55	    let capped_ms = raw_ms.min(config.max_delay.as_millis() as u64);
56	    let jitter_ms = (capped_ms as f64 * config.jitter_factor * jitter_seed) as u64;
57	    Some(Duration::from_millis(capped_ms + jitter_ms))
58	}
