62	/// Handles delay-seconds (integer) format. HTTP-date format is not parsed
63	/// (would require a date library dep) — returns `None` for dates.
64	/// Callers that need date parsing convert to seconds themselves.
65	#[must_use]
66	pub fn parse_retry_after(header_value: &str) -> Option<Duration> {
67	    header_value.trim().parse::<u64>().ok().map(Duration::from_secs)
68	}
